    "ctxApiRefBody": "ctx.ref(val)              — Tạo biến reactive\nctx.computed(fn)          — Tạo thuộc tính computed\nctx.watch(src, cb)        — Theo dõi thay đổi\nctx.onMounted(fn)         — Khi component được mount\nctx.onUnmounted(fn)       — Khi component được unmount\n\nctx.data.client           — Thông tin tài khoản người dùng (reactive)\nctx.data.token            — Token hiện tại (reactive)\nctx.data.isDark           — Chế độ tối (reactive)\n\nctx.api.get(path, query)  — Gửi yêu cầu GET\nctx.api.post(path, body)  — Gửi yêu cầu POST\nctx.api.put(path, body)   — Gửi yêu cầu PUT\nctx.api.delete(path)      — Gửi yêu cầu DELETE\n\nctx.formatBytes(bytes)    — Định dạng kích thước tệp\nctx.formatDate(date)      — Định dạng ngày\nctx.copyText(text)        — Sao chép vào clipboard\nctx.elMessage             — Thông báo Element Plus\nctx.config                — Cấu hình cổng (PORTAL_CONFIG)\nctx.moduleId              — ID mô-đun hiện tại\nctx.moduleTitle           — Tiêu đề mô-đun hiện tại",
